// Checkout conversion fix module
// Ensures paidEvents are recorded when checkout completes

const fs = require('fs');
const path = require('path');

const EVENTS_LOG = '/var/log/unicorn_paid_events.log';

function recordPaidEvent(orderId, amount, currency) {
  const event = {
    orderId,
    amount,
    currency: currency || 'USD',
    timestamp: new Date().toISOString(),
    source: 'checkout-conversion-fix'
  };
  fs.appendFileSync(EVENTS_LOG, JSON.stringify(event) + '\n');
  console.log('[CHECKOUT_FIX] Recorded paid event:', orderId);
  return true;
}

function validateCheckoutFlow(req, res, next) {
  // Intercept checkout completion
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    if (body && body.success && body.orderId) {
      recordPaidEvent(body.orderId, body.amount, body.currency);
    }
    return originalJson(body);
  };
  next();
}

module.exports = { recordPaidEvent, validateCheckoutFlow };
